import 'dart:io';
import 'package:device_info_plus/device_info_plus.dart';

class DeviceInfoService {
  final DeviceInfoPlugin _deviceInfo = DeviceInfoPlugin();

  Future<Map<String, dynamic>> getInfo() async {
    if (Platform.isAndroid) {
      final info = await _deviceInfo.androidInfo;
      return {
        'model': info.model,
        'brand': info.brand,
        'version': info.version.release,
      };
    }
    if (Platform.isIOS) {
      final info = await _deviceInfo.iosInfo;
      return {
        'model': info.utsname.machine,
        'name': info.name,
        'systemVersion': info.systemVersion,
      };
    }
    return {};
  }
}

import 'package:device_info_plus/device_info_plus.dart';
import 'package:flutter/foundation.dart';

Future<Map<String, dynamic>> getWebInfo() async {
  final plugin = DeviceInfoPlugin();
  if (!kIsWeb) return {};
  final info = await plugin.webBrowserInfo;
  return {
    'browser': info.browserName.name,
    'userAgent': info.userAgent,
    'platform': info.platform,
  };
}

import 'package:flutter/material.dart';
import 'device_info_service.dart';

class DeviceInfoPage extends StatefulWidget {
  const DeviceInfoPage({super.key});

  @override
  State<DeviceInfoPage> createState() => _DeviceInfoPageState();
}

class _DeviceInfoPageState extends State<DeviceInfoPage> {
  final service = DeviceInfoService();
  Map<String, dynamic> info = {};

  @override
  void initState() {
    super.initState();
    service.getInfo().then((value) => setState(() => info = value));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Device Info')),
      body: ListView(
        children: info.entries
            .map((e) => ListTile(title: Text(e.key), subtitle: Text('${e.value}')))
            .toList(),
      ),
    );
  }
}

import 'dart:io';
import 'package:device_info_plus/device_info_plus.dart';

Future<bool> isAndroid13OrLater() async {
  if (!Platform.isAndroid) return false;
  final info = await DeviceInfoPlugin().androidInfo;
  return (info.version.sdkInt ?? 0) >= 33;
}
